insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$combien-coute-un-site-web-au-maroc$amw$, $amw$fr$amw$, 1, $amw$Combien coûte un site web au Maroc en 2026 ? Prix et conseils | AMweb$amw$, $amw$Combien coûte un site web au Maroc en 2026 ?$amw$, $amw$Prix d'un site vitrine, e-commerce ou d'une application au Maroc : ce qui fait varier le tarif, les coûts cachés et nos prix dès {{prix:vitrine}} MAD.$amw$, $amw$Prix et budget$amw$, $amw$about$amw$, $amw$La question revient dans presque chaque premier rendez-vous. La réponse honnête : ça dépend de ce que le site doit faire pour vous. Voici comment raisonner, poste par poste, pour savoir combien prévoir et éviter les mauvaises surprises.$amw$, $amw$<h2 id="trois-familles">Les trois grandes familles de sites</h2>
<p>Un <a href="https://fr.wikipedia.org/wiki/Site_web" target="_blank" rel="noopener">site web</a> n'est pas un produit standard. Avant de parler prix, il faut savoir dans quelle catégorie se trouve votre projet.</p>
<ul>
<li><strong>Le site vitrine</strong> présente votre activité : qui vous êtes, ce que vous proposez, comment vous contacter. C'est le point de départ de la plupart des commerces, cabinets et artisans.</li>
<li><strong>Le site e-commerce</strong> vend directement en ligne : catalogue, panier, paiement, gestion des commandes depuis un tableau de bord.</li>
<li><strong>La solution sur mesure</strong> va plus loin : application web ou mobile, CRM, espace client, automatisations. Elle se construit autour de votre façon de travailler.</li>
</ul>

<h2 id="ce-qui-fait-varier">Ce qui fait varier le prix</h2>
<p>Deux sites qui se ressemblent à l'écran peuvent avoir des coûts très différents. Les principaux facteurs :</p>
<ol>
<li><strong>Le nombre de pages et de contenus.</strong> Trois pages bien écrites ne demandent pas le même travail qu'un catalogue de cent produits.</li>
<li><strong>Les fonctionnalités.</strong> Formulaire, réservation, paiement en ligne, espace membre, multilingue : chaque brique ajoute du développement et des tests.</li>
<li><strong>Le design.</strong> Un modèle adapté coûte moins cher qu'une identité dessinée sur mesure, avec animations et parcours étudiés.</li>
<li><strong>Le référencement.</strong> Un site doit être pensé pour Google dès le départ (structure, vitesse, contenus). C'est ce qu'on appelle l'<a href="https://fr.wikipedia.org/wiki/Optimisation_pour_les_moteurs_de_recherche" target="_blank" rel="noopener">optimisation pour les moteurs de recherche</a>.</li>
<li><strong>L'accompagnement.</strong> Hébergement, formation, support et maintenance après la mise en ligne.</li>
</ol>

<h2 id="couts-caches">Les coûts cachés à surveiller</h2>
<p>Un devis bas peut cacher des frais qui arrivent plus tard. Avant de signer, vérifiez toujours :</p>
<ul>
<li><strong>Le nom de domaine et l'hébergement</strong> : sont-ils inclus, et pour combien de temps ? Qui en est propriétaire ?</li>
<li><strong>La maintenance</strong> : mises à jour, sécurité, sauvegardes. Un site non entretenu ralentit et devient vulnérable.</li>
<li><strong>Les modifications</strong> : pouvez-vous changer vous-même un prix ou une photo, ou faut-il payer chaque intervention ?</li>
<li><strong>Le contenu</strong> : textes et photos sont-ils fournis, ou à votre charge ?</li>
</ul>

<h2 id="nos-prix">Nos prix chez AMweb</h2>
<p>Chez AMweb, on affiche nos tarifs clairement, avec des <strong>facilités de paiement</strong> sur toutes les formules :</p>
<div class="prose-prices">
  <a href="../offres.html#vitrine"><span>Site Vitrine</span><strong>{{prix:vitrine}} MAD</strong><small>3 pages sur mesure, SEO de base, hébergement 1 an inclus</small></a>
  <a href="../offres.html#ecommerce"><span>Site E-commerce</span><strong>{{prix:ecommerce}} MAD</strong><small>Boutique complète, paiement intégré, tableau de bord</small></a>
  <a href="../offres.html#premium"><span>Site Premium</span><strong>dès {{prix:premium}} MAD</strong><small>Application, CRM, SEO avancé, prix défini en rendez-vous</small></a>
</div>
<p>Vous hésitez entre deux formules ? Notre <a href="../offres.html#finder">simulateur en quatre questions</a> vous recommande la plus adaptée, avec son prix et son délai réels.</p>

<h2 id="bien-choisir">Comment bien choisir</h2>
<p>Le bon budget n'est pas le plus bas, c'est celui qui vous rapporte le plus de clients. Partez de votre objectif (être trouvé, vendre, automatiser), demandez un devis détaillé et comparez ce qui est réellement inclus. Et si vous avez déjà un site, commencez par notre <a href="../index.html#audit">audit gratuit en 48h</a> : il vous dira ce qui mérite vraiment d'être amélioré.</p>$amw$, $amw$[["Quel est le prix d'un site vitrine au Maroc ?", "Chez AMweb, un site vitrine de 3 pages sur mesure coûte {{prix:vitrine}} MAD, avec SEO de base et hébergement 1 an inclus. Les tarifs du marché varient beaucoup selon le nombre de pages, le design et les fonctionnalités."], ["Peut-on payer un site web en plusieurs fois ?", "Oui. AMweb propose des facilités de paiement sur toutes ses formules, avec un échéancier défini ensemble avant le démarrage du projet."]]$amw$::jsonb, $amw$[{"url": "https://fr.wikipedia.org/wiki/Site_web", "label": "Site web (Wikipédia)"}, {"url": "https://fr.wikipedia.org/wiki/Optimisation_pour_les_moteurs_de_recherche", "label": "Optimisation pour les moteurs de recherche (Wikipédia)"}]$amw$::jsonb, $amw$prix site web Maroc, combien coûte un site web Maroc, tarif création site web, prix site vitrine Maroc, prix site e-commerce Maroc$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$site-vitrine-ou-e-commerce$amw$, $amw$fr$amw$, 2, $amw$Site vitrine ou site e-commerce : lequel choisir ? | AMweb Maroc$amw$, $amw$Site vitrine ou site e-commerce : lequel choisir pour votre activité ?$amw$, $amw$Site vitrine ou boutique en ligne : différences, avantages, cas concrets au Maroc et méthode simple pour choisir la bonne formule selon votre activité.$amw$, $amw$Choisir son site$amw$, $amw$web$amw$, $amw$C'est souvent la première décision d'un projet web. Pourtant la réponse est simple dès qu'on part de la bonne question : est-ce que vos clients doivent pouvoir acheter directement sur votre site ?$amw$, $amw$<h2 id="definitions">Deux outils, deux missions</h2>
<p><strong>Le site vitrine</strong> sert à présenter et à rassurer. Il montre vos services, vos réalisations, vos horaires, et pousse le visiteur à vous appeler, vous écrire sur WhatsApp ou passer vous voir.</p>
<p><strong>Le site e-commerce</strong> sert à vendre. Il ajoute un catalogue, un panier, un paiement et un tableau de bord pour gérer les commandes. C'est ce que Wikipédia appelle le <a href="https://fr.wikipedia.org/wiki/Commerce_en_ligne" target="_blank" rel="noopener">commerce en ligne</a> : l'échange de biens et de services par Internet.</p>

<h2 id="quand-vitrine">Quand choisir un site vitrine</h2>
<ul>
<li>Vous vendez un <strong>service</strong> (cabinet, agence, artisan, clinique, école, restaurant).</li>
<li>Vos ventes se concluent au téléphone, sur WhatsApp ou en boutique.</li>
<li>Vous voulez d'abord <strong>exister sur Google</strong> et inspirer confiance.</li>
</ul>
<p>Chez AMweb, le <a href="../offres.html#vitrine">Site Vitrine</a> coûte {{prix:vitrine}} MAD pour 3 pages sur mesure, livré en {{duree:vitrine}}.</p>

<h2 id="quand-ecommerce">Quand choisir un site e-commerce</h2>
<ul>
<li>Vous vendez des <strong>produits</strong> avec des prix fixes.</li>
<li>Vous recevez beaucoup de demandes répétitives (« c'est combien ? », « il reste la taille M ? »).</li>
<li>Vous voulez vendre <strong>24h/24</strong>, même quand la boutique est fermée.</li>
</ul>
<p>Le <a href="../offres.html#ecommerce">Site E-commerce</a> AMweb coûte {{prix:ecommerce}} MAD : pages illimitées, paiement intégré, tableau de bord et SEO avancé.</p>

<h2 id="hybride">La solution intermédiaire, très utilisée au Maroc</h2>
<p>Beaucoup de commerces marocains démarrent avec un catalogue en ligne et une commande par WhatsApp, puis passent au paiement en ligne quand le volume augmente. C'est une bonne stratégie : vous testez la demande sans tout construire dès le premier jour. Dans tous les cas, votre site doit être parfaitement lisible sur téléphone : c'est le principe du <a href="https://fr.wikipedia.org/wiki/Site_web_r%C3%A9actif" target="_blank" rel="noopener">site web réactif</a>.</p>

<h2 id="methode">La méthode en trois questions</h2>
<ol>
<li>Vos clients peuvent-ils acheter sans vous parler ? Si oui, pensez e-commerce.</li>
<li>Avez-vous plus de 3 pages de contenu à présenter ? Si oui, comparez les deux formules.</li>
<li>Avez-vous besoin d'outils spécifiques (CRM, espace client, application) ? Alors regardez le <a href="../offres.html#premium">Site Premium</a>.</li>
</ol>
<p>Pour aller plus vite, faites le test avec notre <a href="../offres.html#finder">simulateur de forfait</a> : quatre questions, une recommandation claire.</p>$amw$, $amw$[["Quelle est la différence entre un site vitrine et un site e-commerce ?", "Le site vitrine présente votre activité et pousse le visiteur à vous contacter. Le site e-commerce permet d'acheter directement en ligne avec un panier et un paiement."], ["Peut-on transformer un site vitrine en site e-commerce plus tard ?", "Oui. On peut démarrer avec un site vitrine et passer au Site E-commerce quand vous êtes prêt à vendre en ligne."]]$amw$::jsonb, $amw$[{"url": "https://fr.wikipedia.org/wiki/Commerce_en_ligne", "label": "Commerce en ligne (Wikipédia)"}, {"url": "https://fr.wikipedia.org/wiki/Site_web_r%C3%A9actif", "label": "Site web réactif (Wikipédia)"}, {"url": "https://fr.wikipedia.org/wiki/Site_web", "label": "Site web (Wikipédia)"}]$amw$::jsonb, $amw$site vitrine ou e-commerce, différence site vitrine e-commerce, créer boutique en ligne Maroc, site vitrine Maroc$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$pourquoi-un-site-web-entreprise-kenitra$amw$, $amw$fr$amw$, 3, $amw$Pourquoi votre entreprise à Kénitra a besoin d'un site web en 2026 | AMweb$amw$, $amw$Pourquoi votre entreprise à Kénitra a besoin d'un site web en 2026$amw$, $amw$35,5 millions de Marocains sont en ligne. Pourquoi une page Facebook ne suffit plus, et ce qu'un vrai site web change pour une entreprise à Kénitra.$amw$, $amw$Stratégie locale$amw$, $amw$seo$amw$, $amw$Vos futurs clients ont déjà un téléphone en main. La vraie question n'est plus de savoir s'ils vous cherchent en ligne, mais s'ils vous trouvent, et ce qu'ils voient quand ils tombent sur vous.$amw$, $amw$<h2 id="chiffres">Les chiffres qui changent tout</h2>
<p>Selon le rapport <a href="https://datareportal.com/reports/digital-2026-morocco" target="_blank" rel="noopener">Digital 2026 de DataReportal</a> publié fin 2025 :</p>
<ul>
<li><strong>35,5 millions</strong> de personnes utilisent Internet au Maroc, soit <strong>92,2 %</strong> de la population ;</li>
<li><strong>22,8 millions</strong> de comptes sont actifs sur les réseaux sociaux ;</li>
<li>le pays compte <strong>57,1 millions</strong> de connexions mobiles, plus que d'habitants.</li>
</ul>
<p>Autrement dit, presque tous vos clients potentiels sont joignables en ligne, d'abord sur mobile.</p>

<h2 id="kenitra">Kénitra, une ville qui accélère</h2>
<p><a href="https://fr.wikipedia.org/wiki/K%C3%A9nitra" target="_blank" rel="noopener">Kénitra</a> accueille l'Atlantic Free Zone, l'une des plus grandes zones franches d'exportation du continent, et une unité d'assemblage Stellantis. Cette dynamique attire entreprises, sous-traitants et nouveaux habitants. Pour un commerce, un cabinet ou une PME locale, c'est une opportunité, à condition d'être visible là où ces nouveaux clients cherchent : sur Google.</p>

<h2 id="reseaux">Pourquoi une page Facebook ou Instagram ne suffit pas</h2>
<ul>
<li><strong>Vous n'êtes pas chez vous.</strong> L'algorithme décide qui voit vos publications, et un compte peut être bloqué du jour au lendemain.</li>
<li><strong>Google affiche d'abord des sites.</strong> Quand quelqu'un tape « dentiste Kénitra » ou « traiteur Kénitra », il compare des sites et des fiches Google, pas des stories.</li>
<li><strong>La crédibilité.</strong> Un site professionnel avec vos prix, vos réalisations et vos coordonnées rassure plus qu'un fil de publications.</li>
</ul>
<p>Les réseaux sociaux restent indispensables pour attirer l'attention. Le site, lui, transforme cette attention en demandes.</p>

<h2 id="benefices">Ce qu'un vrai site change concrètement</h2>
<ol>
<li>Vous êtes trouvé sur Google, y compris par des clients qui ne vous connaissent pas encore.</li>
<li>Vous répondez aux questions répétitives (prix, horaires, adresse) avant même qu'on vous appelle.</li>
<li>Vous recevez des demandes qualifiées, directement sur WhatsApp.</li>
<li>Vous gardez la main sur votre image et vos contenus.</li>
<li>Vous pouvez vendre en ligne quand vous serez prêt.</li>
</ol>

<h2 id="commencer">Par où commencer</h2>
<p>Commencez simple et bien fait : un <a href="../offres.html#vitrine">site vitrine de 3 pages</a> rapide, clair et optimisé pour Google suffit à faire la différence. Si vous voulez savoir ce que vos concurrents font mieux que vous, demandez notre <a href="../index.html#audit">audit gratuit</a>. Et découvrez notre page dédiée à la <a href="../creation-site-web-kenitra.html">création de site web à Kénitra</a>.</p>$amw$, $amw$[["Combien de Marocains utilisent Internet ?", "Selon DataReportal (Digital 2026), 35,5 millions de personnes utilisent Internet au Maroc, soit 92,2 % de la population."], ["Une page Facebook suffit-elle pour une entreprise ?", "Elle aide à attirer l'attention, mais elle ne remplace pas un site : Google met en avant les sites et les fiches d'établissement, et vous ne contrôlez pas la portée de vos publications sur les réseaux."]]$amw$::jsonb, $amw$[{"url": "https://datareportal.com/reports/digital-2026-morocco", "label": "DataReportal, Digital 2026: Morocco"}, {"url": "https://fr.wikipedia.org/wiki/K%C3%A9nitra", "label": "Kénitra (Wikipédia)"}, {"url": "https://fr.wikipedia.org/wiki/Site_web", "label": "Site web (Wikipédia)"}]$amw$::jsonb, $amw$site web entreprise Kénitra, pourquoi un site web, création site web Kénitra, visibilité en ligne Maroc$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$apparaitre-sur-google-maps-kenitra$amw$, $amw$fr$amw$, 4, $amw$Comment apparaître sur Google Maps et en tête de Google à Kénitra | AMweb$amw$, $amw$Comment apparaître sur Google Maps et en tête de Google à Kénitra$amw$, $amw$Guide pratique du référencement local : fiche Google Business Profile, avis clients, cohérence des coordonnées et site optimisé pour être trouvé à Kénitra.$amw$, $amw$Référencement local$amw$, $amw$listen$amw$, $amw$Quand quelqu'un cherche « restaurant Kénitra » ou « plombier près de moi », Google affiche d'abord une carte avec trois établissements. Être dans ce trio peut remplir votre agenda. Voici comment maximiser vos chances.$amw$, $amw$<h2 id="fiche">1. Créez et vérifiez votre fiche Google Business Profile</h2>
<p>La fiche d'établissement est gratuite. Elle se crée depuis <a href="https://www.google.com/intl/fr/business/" target="_blank" rel="noopener">Google Business Profile</a>. Google vous demandera de vérifier que vous êtes bien le propriétaire avant de l'afficher pleinement.</p>
<ul>
<li>Choisissez la <strong>catégorie principale</strong> la plus précise possible (par exemple « Agence de création de sites Web » plutôt que « Entreprise »).</li>
<li>Renseignez <strong>adresse, téléphone, horaires et site web</strong>.</li>
<li>Ajoutez des <strong>photos réelles</strong> : façade, équipe, produits, réalisations.</li>
</ul>

<h2 id="avis">2. Collectez des avis, régulièrement</h2>
<p>Les avis comptent beaucoup dans le classement local et dans la décision du client. Demandez un avis à chaque client satisfait, avec un lien direct (envoyé par WhatsApp, c'est le plus efficace). Répondez à tous les avis, positifs comme négatifs, de façon courtoise.</p>

<h2 id="coherence">3. Gardez des coordonnées identiques partout</h2>
<p>Nom, adresse et téléphone doivent être écrits exactement de la même façon sur votre fiche Google, votre site, vos réseaux sociaux et les annuaires. Cette cohérence aide Google à faire confiance à vos informations.</p>

<h2 id="site">4. Ayez un site pensé pour le référencement local</h2>
<p>Votre fiche renvoie vers votre site : il doit confirmer ce que Google voit. Concrètement :</p>
<ul>
<li>mentionnez votre ville et votre quartier dans les titres et les textes, naturellement ;</li>
<li>créez une page par service important ;</li>
<li>soignez la vitesse sur mobile (testez avec <a href="https://pagespeed.web.dev/" target="_blank" rel="noopener">PageSpeed Insights</a>) ;</li>
<li>ajoutez les données structurées « LocalBusiness » qui décrivent votre entreprise à Google.</li>
</ul>
<p>Ces bonnes pratiques font partie de l'<a href="https://fr.wikipedia.org/wiki/Optimisation_pour_les_moteurs_de_recherche" target="_blank" rel="noopener">optimisation pour les moteurs de recherche</a>, détaillée dans le <a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr" target="_blank" rel="noopener">guide officiel de Google</a>.</p>

<h2 id="contenu">5. Publiez du contenu utile</h2>
<p>Des pages qui répondent aux vraies questions de vos clients (prix, délais, conseils) attirent des visiteurs qualifiés et montrent votre expertise. C'est exactement ce que fait cette page.</p>

<h2 id="patience">Combien de temps pour voir des résultats ?</h2>
<p>Le référencement est un travail de fond. Comptez généralement plusieurs semaines à quelques mois selon la concurrence dans votre secteur. Personne ne peut garantir une première place, mais une fiche complète, des avis réguliers et un site solide font une vraie différence. Besoin d'aide ? Notre offre <a href="../index.html#services">Référencement SEO</a> s'occupe de tout, et notre <a href="../index.html#audit">audit gratuit</a> vous dit où vous en êtes.</p>$amw$, $amw$[["La fiche Google Business Profile est-elle gratuite ?", "Oui, la création et la gestion d'une fiche Google Business Profile sont gratuites."], ["Peut-on garantir la première place sur Google Maps ?", "Non, personne ne peut le garantir. Une fiche complète et vérifiée, des avis réguliers, des coordonnées cohérentes et un site optimisé augmentent fortement vos chances."]]$amw$::jsonb, $amw$[{"url": "https://www.google.com/intl/fr/business/", "label": "Google Business Profile"}, {"url": "https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr", "label": "Google Search Central, guide de démarrage SEO"}, {"url": "https://fr.wikipedia.org/wiki/Optimisation_pour_les_moteurs_de_recherche", "label": "Optimisation pour les moteurs de recherche (Wikipédia)"}, {"url": "https://pagespeed.web.dev/", "label": "Google PageSpeed Insights"}]$amw$::jsonb, $amw$apparaître sur Google Maps, référencement local Kénitra, fiche Google Business Kénitra, SEO local Maroc$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$crm-pme-maroc$amw$, $amw$fr$amw$, 5, $amw$CRM : à quoi ça sert pour une PME marocaine ? | AMweb$amw$, $amw$CRM : à quoi ça sert pour une PME marocaine ?$amw$, $amw$Définition simple du CRM, signes que votre entreprise en a besoin, CRM du marché ou sur mesure, et comment le connecter à votre site et à WhatsApp.$amw$, $amw$Outils de gestion$amw$, $amw$apps$amw$, $amw$Des contacts dans un téléphone, des devis dans Excel, des relances oubliées sur WhatsApp : si cette scène vous parle, un CRM peut vous faire gagner du temps et des clients.$amw$, $amw$<h2 id="definition">Un CRM, c'est quoi ?</h2>
<p>Un CRM (Customer Relationship Management), en français <a href="https://fr.wikipedia.org/wiki/Gestion_de_la_relation_client" target="_blank" rel="noopener">gestion de la relation client</a>, est un outil qui centralise tout ce qui concerne vos clients et prospects : coordonnées, échanges, devis, commandes, relances.</p>

<h2 id="signes">Les signes que vous en avez besoin</h2>
<ul>
<li>Vous perdez des demandes parce qu'elles arrivent par trop de canaux (téléphone, WhatsApp, Instagram, formulaire).</li>
<li>Vous ne savez pas combien de devis sont en attente, ni lesquels relancer.</li>
<li>Plusieurs personnes de l'équipe répondent aux clients sans voir l'historique.</li>
<li>Vous voulez des chiffres : d'où viennent vos clients, combien vous rapporte chaque source.</li>
</ul>

<h2 id="benefices">Ce qu'un CRM change au quotidien</h2>
<ol>
<li><strong>Tout au même endroit</strong> : chaque client a sa fiche, avec l'historique complet.</li>
<li><strong>Aucune relance oubliée</strong> : rappels automatiques pour les devis et les rendez-vous.</li>
<li><strong>Une équipe alignée</strong> : chacun voit où en est chaque dossier.</li>
<li><strong>Des décisions basées sur des chiffres</strong> : tableaux de bord simples et lisibles.</li>
</ol>

<h2 id="marche-ou-mesure">CRM du marché ou CRM sur mesure ?</h2>
<p>Les CRM prêts à l'emploi conviennent à beaucoup d'entreprises, mais ils imposent leur logique, souvent en anglais, avec un abonnement par utilisateur. Un CRM <strong>sur mesure</strong> s'adapte à votre métier : vos étapes de vente, vos documents, vos rôles, en français ou en arabe. Il se connecte directement à votre site web (chaque formulaire crée une fiche) et à vos outils existants.</p>

<h2 id="connecter">Le connecter à votre site et à WhatsApp</h2>
<p>La vraie puissance arrive quand le CRM est relié à vos canaux : une demande sur votre site crée automatiquement une fiche, un message de confirmation part, et la relance est programmée. Résultat : moins de saisie, plus de réactivité.</p>

<h2 id="prix">Combien ça coûte ?</h2>
<p>Chez AMweb, les CRM et applications sur mesure font partie du <a href="../offres.html#premium">Site Premium</a>, à partir de {{prix:premium}} MAD. Le prix exact se définit ensemble lors d'un rendez-vous, selon vos besoins, avec des facilités de paiement. Découvrez aussi notre expertise <a href="../index.html#services">Applications &amp; CRM</a>.</p>$amw$, $amw$[["Qu'est-ce qu'un CRM ?", "Un CRM (gestion de la relation client) est un outil qui centralise les informations sur vos clients et prospects : coordonnées, échanges, devis, commandes et relances."], ["Combien coûte un CRM sur mesure au Maroc ?", "Chez AMweb, les CRM sur mesure font partie du Site Premium, à partir de {{prix:premium}} MAD. Le prix exact est défini lors d'un rendez-vous selon vos besoins."]]$amw$::jsonb, $amw$[{"url": "https://fr.wikipedia.org/wiki/Gestion_de_la_relation_client", "label": "Gestion de la relation client (Wikipédia)"}]$amw$::jsonb, $amw$CRM Maroc, CRM PME Maroc, logiciel gestion clients Maroc, CRM sur mesure, application gestion entreprise Maroc$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$vendre-en-ligne-au-maroc$amw$, $amw$fr$amw$, 6, $amw$Vendre en ligne au Maroc : paiement, livraison et règles à connaître | AMweb$amw$, $amw$Vendre en ligne au Maroc : paiement, livraison et règles à connaître$amw$, $amw$Lancer une boutique en ligne au Maroc : moyens de paiement, paiement à la livraison, livraison, lois 31-08 et 09-08, et pages indispensables.$amw$, $amw$E-commerce$amw$, $amw$marketing$amw$, $amw$Ouvrir une boutique en ligne au Maroc n'a jamais été aussi accessible. Mais une boutique qui vend vraiment repose sur quelques choix clés : comment vos clients paient, comment ils sont livrés, et ce qui les rassure avant d'acheter.$amw$, $amw$<h2 id="produits">Commencez par vos produits</h2>
<p>Les meilleures boutiques démarrent avec une offre claire : quelques produits phares bien présentés valent mieux qu'un catalogue immense mal décrit. Chaque fiche produit doit avoir de vraies photos, un prix, une description précise et les délais de livraison.</p>

<h2 id="paiement">Les moyens de paiement</h2>
<ul>
<li><strong>Le paiement par carte</strong> : au Maroc, il passe par une solution de paiement reliée au <a href="https://www.cmi.co.ma/" target="_blank" rel="noopener">Centre Monétique Interbancaire (CMI)</a> ou par un prestataire agréé, via votre banque.</li>
<li><strong>Le paiement à la livraison</strong> : très répandu au Maroc, il rassure les clients qui commandent pour la première fois.</li>
<li><strong>Le virement</strong> : utile pour les commandes importantes ou les clients professionnels.</li>
</ul>
<p>Proposer plusieurs options réduit les abandons de panier. Le <a href="../offres.html#ecommerce">Site E-commerce AMweb</a> intègre le paiement en ligne et s'adapte à ces modes.</p>

<h2 id="livraison">La livraison</h2>
<p>Choisissez un partenaire de livraison fiable qui couvre les villes de vos clients, affichez clairement les frais et les délais, et envoyez un message de suivi. Une livraison bien gérée transforme un premier achat en client fidèle.</p>

<h2 id="regles">Les règles à connaître</h2>
<ul>
<li><strong>Protection du consommateur</strong> : la loi 31-08 encadre la vente à distance, notamment l'information du client et le droit de rétractation.</li>
<li><strong>Données personnelles</strong> : la loi 09-08 impose de protéger les données de vos clients et d'informer sur leur utilisation. La <a href="https://www.cndp.ma/" target="_blank" rel="noopener">CNDP</a> est l'autorité compétente.</li>
<li><strong>Pages obligatoires</strong> : mentions légales, conditions générales de vente, politique de confidentialité.</li>
</ul>
<p>Faites relire vos conditions générales par un professionnel du droit : ce guide ne remplace pas un conseil juridique.</p>

<h2 id="confiance">Ce qui rassure avant l'achat</h2>
<ol>
<li>Un site rapide et impeccable sur mobile ;</li>
<li>des avis clients visibles ;</li>
<li>un numéro WhatsApp pour poser une question ;</li>
<li>des conditions de retour claires ;</li>
<li>un site sécurisé en HTTPS.</li>
</ol>

<h2 id="lancer">Prêt à vous lancer ?</h2>
<p>Le <a href="https://fr.wikipedia.org/wiki/Commerce_en_ligne" target="_blank" rel="noopener">commerce en ligne</a> récompense ceux qui démarrent bien. Notre <a href="../offres.html#ecommerce">Site E-commerce à {{prix:ecommerce}} MAD</a> comprend boutique complète, paiement intégré, tableau de bord, SEO avancé et support prioritaire, avec des facilités de paiement. Lisez aussi notre comparatif <a href="site-vitrine-ou-e-commerce.html">site vitrine ou e-commerce</a>.</p>$amw$, $amw$[["Le paiement à la livraison est-il possible sur une boutique en ligne ?", "Oui, et il est très répandu au Maroc. On peut le proposer à côté du paiement par carte pour rassurer les nouveaux clients."], ["Quelles pages légales faut-il sur une boutique en ligne au Maroc ?", "Au minimum des mentions légales, des conditions générales de vente et une politique de confidentialité conforme à la loi 09-08. Faites-les valider par un professionnel du droit."]]$amw$::jsonb, $amw$[{"url": "https://fr.wikipedia.org/wiki/Commerce_en_ligne", "label": "Commerce en ligne (Wikipédia)"}, {"url": "https://www.cmi.co.ma/", "label": "CMI, Centre Monétique Interbancaire"}, {"url": "https://www.cndp.ma/", "label": "CNDP, Commission nationale de contrôle de la protection des données à caractère personnel"}]$amw$::jsonb, $amw$vendre en ligne Maroc, créer boutique en ligne Maroc, paiement en ligne Maroc, e-commerce Maroc, paiement à la livraison Maroc$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$combien-coute-un-site-web-au-maroc$amw$, $amw$en$amw$, 1, $amw$How much does a website cost in Morocco in 2026? Prices and tips | AMweb$amw$, $amw$How much does a website cost in Morocco in 2026?$amw$, $amw$Prices for a showcase website, an online store or an app in Morocco: what drives the cost, hidden fees to watch for, and our prices from {{prix:vitrine}} MAD.$amw$, $amw$Price and budget$amw$, $amw$about$amw$, $amw$It comes up in almost every first meeting. The honest answer: it depends on what the website has to do for you. Here is how to think it through, item by item, so you know what to budget and avoid bad surprises.$amw$, $amw$<h2 id="trois-familles">The three main types of websites</h2>
<p>A <a href="https://en.wikipedia.org/wiki/Website" target="_blank" rel="noopener">website</a> is not a standard product. Before talking about price, you need to know which category your project belongs to.</p>
<ul>
<li><strong>The showcase website</strong> presents your business: who you are, what you offer, how to reach you. It is the starting point for most shops, practices and craftspeople.</li>
<li><strong>The e-commerce website</strong> sells directly online: catalog, cart, payment and order management from a dashboard.</li>
<li><strong>The custom solution</strong> goes further: web or mobile app, CRM, client area, automations. It is built around the way you work.</li>
</ul>

<h2 id="ce-qui-fait-varier">What drives the price</h2>
<p>Two websites that look alike on screen can cost very different amounts. The main factors:</p>
<ol>
<li><strong>The number of pages and the amount of content.</strong> Three well-written pages do not take the same work as a catalog of a hundred products.</li>
<li><strong>Features.</strong> Contact form, booking, online payment, member area, several languages: each building block adds development and testing.</li>
<li><strong>Design.</strong> An adapted template costs less than a custom-drawn identity with animations and carefully designed user journeys.</li>
<li><strong>Search engine visibility.</strong> A website must be built for Google from day one (structure, speed, content). This is called <a href="https://en.wikipedia.org/wiki/Search_engine_optimization" target="_blank" rel="noopener">search engine optimization</a>.</li>
<li><strong>Support.</strong> Hosting, training, help and maintenance after launch.</li>
</ol>

<h2 id="couts-caches">Hidden costs to watch for</h2>
<p>A low quote can hide fees that show up later. Before signing, always check:</p>
<ul>
<li><strong>Domain name and hosting</strong>: are they included, and for how long? Who owns them?</li>
<li><strong>Maintenance</strong>: updates, security, backups. A website that is not maintained slows down and becomes vulnerable.</li>
<li><strong>Changes</strong>: can you update a price or a photo yourself, or do you pay for every change?</li>
<li><strong>Content</strong>: are texts and photos provided, or up to you?</li>
</ul>

<h2 id="nos-prix">Our prices at AMweb</h2>
<p>At AMweb, our prices are clearly displayed, with <strong>payment plans</strong> on every package:</p>
<div class="prose-prices">
  <a href="../offres.html#vitrine"><span>Showcase Site</span><strong>{{prix:vitrine}} MAD</strong><small>3 custom pages, basic SEO, 1 year of hosting included</small></a>
  <a href="../offres.html#ecommerce"><span>E-commerce Site</span><strong>{{prix:ecommerce}} MAD</strong><small>Complete store, integrated payment, dashboard</small></a>
  <a href="../offres.html#premium"><span>Premium Site</span><strong>from {{prix:premium}} MAD</strong><small>App, CRM, advanced SEO, price set during a meeting</small></a>
</div>
<p>Torn between two packages? Our <a href="../offres.html#finder">four-question simulator</a> recommends the best fit, with its real price and timeline.</p>

<h2 id="bien-choisir">How to choose well</h2>
<p>The right budget is not the lowest one, it is the one that brings you the most clients. Start from your goal (being found, selling, automating), ask for a detailed quote and compare what is really included. If you already have a website, start with our <a href="../index.html#audit">free 48-hour audit</a>: it tells you what is really worth improving.</p>$amw$, $amw$[["How much does a showcase website cost in Morocco?", "At AMweb, a custom 3-page showcase website costs {{prix:vitrine}} MAD, with basic SEO and 1 year of hosting included. Market prices vary widely depending on the number of pages, the design and the features."], ["Can I pay for a website in installments?", "Yes. AMweb offers payment plans on all its packages, with a schedule agreed together before the project starts."]]$amw$::jsonb, $amw$[{"url": "https://en.wikipedia.org/wiki/Website", "label": "Website (Wikipedia)"}, {"url": "https://en.wikipedia.org/wiki/Search_engine_optimization", "label": "Search engine optimization (Wikipedia)"}]$amw$::jsonb, $amw$website price Morocco, how much does a website cost Morocco, web design cost Morocco, showcase website price, e-commerce website price Morocco$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$site-vitrine-ou-e-commerce$amw$, $amw$en$amw$, 2, $amw$Showcase website or online store: which one to choose? | AMweb Morocco$amw$, $amw$Showcase website or online store: which one is right for your business?$amw$, $amw$Showcase website or online store: differences, benefits, real cases in Morocco and a simple method to choose the right package for your business.$amw$, $amw$Choosing a website$amw$, $amw$web$amw$, $amw$It is often the first decision in a web project. Yet the answer is simple once you ask the right question: should your clients be able to buy directly on your website?$amw$, $amw$<h2 id="definitions">Two tools, two missions</h2>
<p><strong>The showcase website</strong> presents and reassures. It shows your services, your work and your opening hours, and encourages visitors to call you, message you on WhatsApp or drop by.</p>
<p><strong>The e-commerce website</strong> sells. It adds a catalog, a cart, a payment step and a dashboard to manage orders. This is what Wikipedia calls <a href="https://en.wikipedia.org/wiki/E-commerce" target="_blank" rel="noopener">e-commerce</a>: buying and selling goods and services over the Internet.</p>

<h2 id="quand-vitrine">When to choose a showcase website</h2>
<ul>
<li>You sell a <strong>service</strong> (practice, agency, craftsperson, clinic, school, restaurant).</li>
<li>Your sales are closed by phone, on WhatsApp or in store.</li>
<li>You first want to <strong>exist on Google</strong> and build trust.</li>
</ul>
<p>At AMweb, the <a href="../offres.html#vitrine">Showcase Site</a> costs {{prix:vitrine}} MAD for 3 custom pages, delivered in {{duree:vitrine}}.</p>

<h2 id="quand-ecommerce">When to choose an online store</h2>
<ul>
<li>You sell <strong>products</strong> at fixed prices.</li>
<li>You get a lot of repetitive questions ("how much is it?", "do you still have size M?").</li>
<li>You want to sell <strong>24/7</strong>, even when your shop is closed.</li>
</ul>
<p>The AMweb <a href="../offres.html#ecommerce">E-commerce Site</a> costs {{prix:ecommerce}} MAD: unlimited pages, integrated payment, dashboard and advanced SEO.</p>

<h2 id="hybride">The in-between option, very common in Morocco</h2>
<p>Many Moroccan businesses start with an online catalog and ordering through WhatsApp, then add online payment as volume grows. It is a good strategy: you test demand without building everything on day one. Either way, your website must be perfectly readable on a phone: that is the principle of <a href="https://en.wikipedia.org/wiki/Responsive_web_design" target="_blank" rel="noopener">responsive web design</a>.</p>

<h2 id="methode">The three-question method</h2>
<ol>
<li>Can your clients buy without talking to you? If so, think e-commerce.</li>
<li>Do you have more than 3 pages of content to present? If so, compare both packages.</li>
<li>Do you need specific tools (CRM, client area, app)? Then look at the <a href="../offres.html#premium">Premium Site</a>.</li>
</ol>
<p>To decide faster, take the test with our <a href="../offres.html#finder">package simulator</a>: four questions, one clear recommendation.</p>$amw$, $amw$[["What is the difference between a showcase website and an online store?", "A showcase website presents your business and encourages visitors to contact you. An online store lets people buy directly online, with a cart and a payment step."], ["Can a showcase website become an online store later?", "Yes. You can start with a showcase website and move to the E-commerce Site when you are ready to sell online."]]$amw$::jsonb, $amw$[{"url": "https://en.wikipedia.org/wiki/E-commerce", "label": "E-commerce (Wikipedia)"}, {"url": "https://en.wikipedia.org/wiki/Responsive_web_design", "label": "Responsive web design (Wikipedia)"}, {"url": "https://en.wikipedia.org/wiki/Website", "label": "Website (Wikipedia)"}]$amw$::jsonb, $amw$showcase website or e-commerce, difference showcase website online store, create online store Morocco, showcase website Morocco$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$pourquoi-un-site-web-entreprise-kenitra$amw$, $amw$en$amw$, 3, $amw$Why your business in Kénitra needs a website in 2026 | AMweb$amw$, $amw$Why your business in Kénitra needs a website in 2026$amw$, $amw$35.5 million Moroccans are online. Why a Facebook page is no longer enough, and what a real website changes for a business in Kénitra.$amw$, $amw$Local strategy$amw$, $amw$seo$amw$, $amw$Your future clients already have a phone in hand. The real question is no longer whether they look for you online, but whether they find you, and what they see when they do.$amw$, $amw$<h2 id="chiffres">The numbers that change everything</h2>
<p>According to the <a href="https://datareportal.com/reports/digital-2026-morocco" target="_blank" rel="noopener">DataReportal Digital 2026 report</a> published at the end of 2025:</p>
<ul>
<li><strong>35.5 million</strong> people use the Internet in Morocco, that is <strong>92.2%</strong> of the population;</li>
<li><strong>22.8 million</strong> social media accounts are active;</li>
<li>the country has <strong>57.1 million</strong> mobile connections, more than its population.</li>
</ul>
<p>In other words, almost all your potential clients can be reached online, mostly on mobile.</p>

<h2 id="kenitra">Kénitra, a city on the rise</h2>
<p><a href="https://en.wikipedia.org/wiki/Kenitra" target="_blank" rel="noopener">Kénitra</a> is home to the Atlantic Free Zone, one of the largest export free zones on the continent, and a Stellantis assembly plant. This momentum attracts companies, subcontractors and new residents. For a local shop, practice or small business, it is an opportunity, as long as you are visible where these new clients search: on Google.</p>

<h2 id="reseaux">Why a Facebook or Instagram page is not enough</h2>
<ul>
<li><strong>You are not at home.</strong> The algorithm decides who sees your posts, and an account can be blocked overnight.</li>
<li><strong>Google shows websites first.</strong> When someone types "dentist Kénitra" or "caterer Kénitra", they compare websites and Google listings, not stories.</li>
<li><strong>Credibility.</strong> A professional website with your prices, your work and your contact details reassures more than a feed of posts.</li>
</ul>
<p>Social media remains essential to get attention. The website turns that attention into requests.</p>

<h2 id="benefices">What a real website actually changes</h2>
<ol>
<li>You are found on Google, including by clients who do not know you yet.</li>
<li>You answer repetitive questions (prices, opening hours, address) before anyone calls you.</li>
<li>You receive qualified requests, straight to WhatsApp.</li>
<li>You stay in control of your image and your content.</li>
<li>You can sell online when you are ready.</li>
</ol>

<h2 id="commencer">Where to start</h2>
<p>Start simple and well done: a fast, clear <a href="../offres.html#vitrine">3-page showcase website</a> optimized for Google is enough to make a difference. If you want to know what your competitors do better than you, ask for our <a href="../index.html#audit">free audit</a>.</p>$amw$, $amw$[["How many Moroccans use the Internet?", "According to DataReportal (Digital 2026), 35.5 million people use the Internet in Morocco, that is 92.2% of the population."], ["Is a Facebook page enough for a business?", "It helps to get attention, but it does not replace a website: Google highlights websites and business listings, and you do not control the reach of your posts on social media."]]$amw$::jsonb, $amw$[{"url": "https://datareportal.com/reports/digital-2026-morocco", "label": "DataReportal, Digital 2026: Morocco"}, {"url": "https://en.wikipedia.org/wiki/Kenitra", "label": "Kenitra (Wikipedia)"}, {"url": "https://en.wikipedia.org/wiki/Website", "label": "Website (Wikipedia)"}]$amw$::jsonb, $amw$business website Kénitra, why a website, web design Kénitra, online visibility Morocco$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$apparaitre-sur-google-maps-kenitra$amw$, $amw$en$amw$, 4, $amw$How to appear on Google Maps and at the top of Google in Kénitra | AMweb$amw$, $amw$How to appear on Google Maps and at the top of Google in Kénitra$amw$, $amw$A practical guide to local SEO: Google Business Profile, client reviews, consistent contact details and an optimized website to be found in Kénitra.$amw$, $amw$Local SEO$amw$, $amw$listen$amw$, $amw$When someone searches for "restaurant Kénitra" or "plumber near me", Google first shows a map with three businesses. Being in that trio can fill your calendar. Here is how to maximize your chances.$amw$, $amw$<h2 id="fiche">1. Create and verify your Google Business Profile</h2>
<p>The business listing is free. You create it from <a href="https://www.google.com/business/" target="_blank" rel="noopener">Google Business Profile</a>. Google will ask you to verify that you are the owner before showing it fully.</p>
<ul>
<li>Choose the most precise <strong>primary category</strong> possible (for example "Website designer" rather than "Company").</li>
<li>Fill in your <strong>address, phone number, opening hours and website</strong>.</li>
<li>Add <strong>real photos</strong>: storefront, team, products, past work.</li>
</ul>

<h2 id="avis">2. Collect reviews, regularly</h2>
<p>Reviews matter a lot in local rankings and in the client's decision. Ask every satisfied client for a review, with a direct link (sending it on WhatsApp works best). Reply to every review, positive or negative, politely.</p>

<h2 id="coherence">3. Keep identical contact details everywhere</h2>
<p>Name, address and phone number must be written exactly the same way on your Google listing, your website, your social media and in directories. This consistency helps Google trust your information.</p>

<h2 id="site">4. Have a website built for local search</h2>
<p>Your listing links to your website: it has to confirm what Google sees. In practice:</p>
<ul>
<li>mention your city and neighborhood in titles and texts, naturally;</li>
<li>create one page per important service;</li>
<li>take care of mobile speed (test it with <a href="https://pagespeed.web.dev/" target="_blank" rel="noopener">PageSpeed Insights</a>);</li>
<li>add "LocalBusiness" structured data that describes your business to Google.</li>
</ul>
<p>These good practices are part of <a href="https://en.wikipedia.org/wiki/Search_engine_optimization" target="_blank" rel="noopener">search engine optimization</a>, detailed in <a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide" target="_blank" rel="noopener">Google's official guide</a>.</p>

<h2 id="contenu">5. Publish useful content</h2>
<p>Pages that answer your clients' real questions (prices, timelines, advice) attract qualified visitors and show your expertise. That is exactly what this page does.</p>

<h2 id="patience">How long before you see results?</h2>
<p>Search visibility is long-term work. It usually takes several weeks to a few months depending on the competition in your sector. Nobody can guarantee first place, but a complete listing, regular reviews and a solid website make a real difference. Need help? Our <a href="../index.html#services">SEO</a> service takes care of everything, and our <a href="../index.html#audit">free audit</a> tells you where you stand.</p>$amw$, $amw$[["Is Google Business Profile free?", "Yes, creating and managing a Google Business Profile listing is free."], ["Can anyone guarantee first place on Google Maps?", "No, nobody can guarantee it. A complete and verified listing, regular reviews, consistent contact details and an optimized website greatly increase your chances."]]$amw$::jsonb, $amw$[{"url": "https://www.google.com/business/", "label": "Google Business Profile"}, {"url": "https://developers.google.com/search/docs/fundamentals/seo-starter-guide", "label": "Google Search Central, SEO Starter Guide"}, {"url": "https://en.wikipedia.org/wiki/Search_engine_optimization", "label": "Search engine optimization (Wikipedia)"}, {"url": "https://pagespeed.web.dev/", "label": "Google PageSpeed Insights"}]$amw$::jsonb, $amw$appear on Google Maps, local SEO Kénitra, Google Business Kénitra, local SEO Morocco$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$crm-pme-maroc$amw$, $amw$en$amw$, 5, $amw$CRM: what is it for in a Moroccan small business? | AMweb$amw$, $amw$CRM: what is it for in a Moroccan small business?$amw$, $amw$A simple definition of CRM, signs your business needs one, off-the-shelf or custom CRM, and how to connect it to your website and WhatsApp.$amw$, $amw$Management tools$amw$, $amw$apps$amw$, $amw$Contacts in a phone, quotes in Excel, follow-ups forgotten on WhatsApp: if this sounds familiar, a CRM can save you time and win you clients.$amw$, $amw$<h2 id="definition">What is a CRM?</h2>
<p>A CRM (<a href="https://en.wikipedia.org/wiki/Customer_relationship_management" target="_blank" rel="noopener">customer relationship management</a>) is a tool that centralizes everything about your clients and prospects: contact details, conversations, quotes, orders and follow-ups.</p>

<h2 id="signes">Signs that you need one</h2>
<ul>
<li>You lose requests because they come through too many channels (phone, WhatsApp, Instagram, forms).</li>
<li>You do not know how many quotes are pending, or which ones to follow up.</li>
<li>Several people on the team answer clients without seeing the history.</li>
<li>You want numbers: where your clients come from, and how much each source brings in.</li>
</ul>

<h2 id="benefices">What a CRM changes day to day</h2>
<ol>
<li><strong>Everything in one place</strong>: each client has a profile with the full history.</li>
<li><strong>No forgotten follow-ups</strong>: automatic reminders for quotes and appointments.</li>
<li><strong>An aligned team</strong>: everyone sees where each file stands.</li>
<li><strong>Decisions based on numbers</strong>: simple, readable dashboards.</li>
</ol>

<h2 id="marche-ou-mesure">Off-the-shelf or custom CRM?</h2>
<p>Ready-made CRMs suit many businesses, but they impose their own logic, often in English only, with a per-user subscription. A <strong>custom</strong> CRM adapts to your trade: your sales steps, your documents, your roles, in French or Arabic. It connects directly to your website (every form creates a client profile) and to the tools you already use.</p>

<h2 id="connecter">Connect it to your website and WhatsApp</h2>
<p>The real power comes when the CRM is linked to your channels: a request on your website automatically creates a profile, a confirmation message goes out, and the follow-up is scheduled. The result: less data entry, more responsiveness.</p>

<h2 id="prix">How much does it cost?</h2>
<p>At AMweb, custom CRMs and apps are part of the <a href="../offres.html#premium">Premium Site</a>, from {{prix:premium}} MAD. The exact price is set together during a meeting, based on your needs, with payment plans. See also our <a href="../index.html#services">Apps &amp; CRM</a> expertise.</p>$amw$, $amw$[["What is a CRM?", "A CRM (customer relationship management) is a tool that centralizes information about your clients and prospects: contact details, conversations, quotes, orders and follow-ups."], ["How much does a custom CRM cost in Morocco?", "At AMweb, custom CRMs are part of the Premium Site, from {{prix:premium}} MAD. The exact price is set during a meeting based on your needs."]]$amw$::jsonb, $amw$[{"url": "https://en.wikipedia.org/wiki/Customer_relationship_management", "label": "Customer relationship management (Wikipedia)"}]$amw$::jsonb, $amw$CRM Morocco, CRM small business Morocco, client management software Morocco, custom CRM, business app Morocco$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$vendre-en-ligne-au-maroc$amw$, $amw$en$amw$, 6, $amw$Selling online in Morocco: payment, delivery and rules to know | AMweb$amw$, $amw$Selling online in Morocco: payment, delivery and rules to know$amw$, $amw$Launching an online store in Morocco: payment methods, cash on delivery, shipping, legal obligations (Law 31-08, Law 09-08) and must-have pages.$amw$, $amw$E-commerce$amw$, $amw$marketing$amw$, $amw$Opening an online store in Morocco has never been easier. But a store that really sells relies on a few key choices: how your clients pay, how they get their orders, and what reassures them before they buy.$amw$, $amw$<h2 id="produits">Start with your products</h2>
<p>The best stores start with a clear offer: a few well-presented best-sellers beat a huge, poorly described catalog. Every product page needs real photos, a price, a precise description and delivery times.</p>

<h2 id="paiement">Payment methods</h2>
<ul>
<li><strong>Card payment</strong>: in Morocco, it goes through a payment solution connected to the <a href="https://www.cmi.co.ma/" target="_blank" rel="noopener">Centre Monétique Interbancaire (CMI)</a> or through an approved provider, via your bank.</li>
<li><strong>Cash on delivery</strong>: very common in Morocco, it reassures clients who order for the first time.</li>
<li><strong>Bank transfer</strong>: useful for large orders or business clients.</li>
</ul>
<p>Offering several options reduces abandoned carts. The <a href="../offres.html#ecommerce">AMweb E-commerce Site</a> includes online payment and adapts to these methods.</p>

<h2 id="livraison">Delivery</h2>
<p>Choose a reliable delivery partner that covers your clients' cities, clearly show fees and timelines, and send a tracking message. Well-handled delivery turns a first purchase into a loyal client.</p>

<h2 id="regles">Rules to know</h2>
<ul>
<li><strong>Consumer protection</strong>: Law 31-08 governs distance selling, including the information given to the client and the right of withdrawal.</li>
<li><strong>Personal data</strong>: Law 09-08 requires you to protect your clients' data and to explain how it is used. The <a href="https://www.cndp.ma/" target="_blank" rel="noopener">CNDP</a> is the competent authority.</li>
<li><strong>Required pages</strong>: legal notice, terms and conditions of sale, privacy policy.</li>
</ul>
<p>Have your terms of sale reviewed by a legal professional: this guide does not replace legal advice.</p>

<h2 id="confiance">What reassures before buying</h2>
<ol>
<li>A fast website that works perfectly on mobile;</li>
<li>visible client reviews;</li>
<li>a WhatsApp number to ask a question;</li>
<li>clear return conditions;</li>
<li>a secure HTTPS website.</li>
</ol>

<h2 id="lancer">Ready to launch?</h2>
<p><a href="https://en.wikipedia.org/wiki/E-commerce" target="_blank" rel="noopener">E-commerce</a> rewards those who start well. Our <a href="../offres.html#ecommerce">E-commerce Site at {{prix:ecommerce}} MAD</a> includes a complete store, integrated payment, a dashboard, advanced SEO and priority support, with payment plans. Read also our comparison <a href="site-vitrine-ou-e-commerce.html">showcase website or online store</a>.</p>$amw$, $amw$[["Is cash on delivery possible on an online store?", "Yes, and it is very common in Morocco. It can be offered alongside card payment to reassure new clients."], ["Which legal pages does an online store in Morocco need?", "At least a legal notice, terms and conditions of sale and a privacy policy compliant with Law 09-08. Have them reviewed by a legal professional."]]$amw$::jsonb, $amw$[{"url": "https://en.wikipedia.org/wiki/E-commerce", "label": "E-commerce (Wikipedia)"}, {"url": "https://www.cmi.co.ma/", "label": "CMI, Centre Monétique Interbancaire"}, {"url": "https://www.cndp.ma/", "label": "CNDP, Morocco's personal data protection authority"}]$amw$::jsonb, $amw$sell online Morocco, create online store Morocco, online payment Morocco, e-commerce Morocco, cash on delivery Morocco$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$combien-coute-un-site-web-au-maroc$amw$, $amw$ar$amw$, 1, $amw$كم يكلف موقع إلكتروني في المغرب سنة 2026؟ الأسعار والنصائح | AMweb$amw$, $amw$كم يكلف موقع إلكتروني في المغرب سنة 2026؟$amw$, $amw$سعر الموقع التعريفي أو المتجر الإلكتروني أو التطبيق في المغرب: ما الذي يحدد التكلفة، والمصاريف الخفية التي يجب الانتباه إليها، وأسعارنا ابتداءً من {{prix:vitrine}} درهم.$amw$, $amw$السعر والميزانية$amw$, $amw$about$amw$, $amw$هذا السؤال يُطرح في كل موعد أول تقريباً. والجواب الصادق: يتوقف ذلك على ما يجب أن يحققه الموقع لك. إليك طريقة التفكير فيه، بنداً بنداً، لتعرف الميزانية المناسبة وتتجنب المفاجآت.$amw$, $amw$<h2 id="trois-familles">الأنواع الثلاثة الكبرى للمواقع</h2>
<p><a href="https://ar.wikipedia.org/wiki/%D9%85%D9%88%D9%82%D8%B9_%D9%88%D9%8A%D8%A8" target="_blank" rel="noopener">الموقع الإلكتروني</a> ليس منتجاً جاهزاً بمقاس واحد. قبل الحديث عن السعر، يجب أن تعرف إلى أي فئة ينتمي مشروعك.</p>
<ul>
<li><strong>الموقع التعريفي</strong> يقدّم نشاطك: من أنت، وماذا تقدّم، وكيف يمكن التواصل معك. إنه نقطة البداية لأغلب المحلات والعيادات والمكاتب والحرفيين.</li>
<li><strong>المتجر الإلكتروني</strong> يبيع مباشرة عبر الإنترنت: كتالوج، سلة مشتريات، أداء، وتسيير الطلبات من لوحة تحكم.</li>
<li><strong>الحل حسب الطلب</strong> يذهب أبعد من ذلك: تطبيق ويب أو هاتف، نظام CRM، فضاء خاص بالعملاء، أتمتة المهام. يُبنى حول طريقة عملك.</li>
</ul>

<h2 id="ce-qui-fait-varier">ما الذي يحدد السعر</h2>
<p>قد يتشابه موقعان على الشاشة وتختلف تكلفتهما كثيراً. أهم العوامل:</p>
<ol>
<li><strong>عدد الصفحات وحجم المحتوى.</strong> ثلاث صفحات مكتوبة بعناية لا تتطلب نفس العمل الذي يتطلبه كتالوج من مئة منتج.</li>
<li><strong>الخصائص.</strong> استمارة تواصل، حجز، أداء إلكتروني، فضاء للأعضاء، تعدد اللغات: كل إضافة تتطلب تطويراً واختبارات.</li>
<li><strong>التصميم.</strong> قالب مُكيَّف أقل تكلفة من هوية بصرية مصممة حسب الطلب مع حركات ومسارات استخدام مدروسة.</li>
<li><strong>الظهور في محركات البحث.</strong> يجب أن يُبنى الموقع لـ Google منذ البداية (البنية، السرعة، المحتوى). وهذا ما يسمى <a href="https://ar.wikipedia.org/wiki/%D8%AA%D8%AD%D8%B3%D9%8A%D9%86_%D9%85%D8%AD%D8%B1%D9%83%D8%A7%D8%AA_%D8%A7%D9%84%D8%A8%D8%AD%D8%AB" target="_blank" rel="noopener">تحسين محركات البحث</a>.</li>
<li><strong>المرافقة.</strong> الاستضافة، التكوين، الدعم والصيانة بعد الإطلاق.</li>
</ol>

<h2 id="couts-caches">المصاريف الخفية التي يجب الانتباه إليها</h2>
<p>قد يُخفي عرض السعر المنخفض مصاريف تظهر لاحقاً. قبل التوقيع، تحقق دائماً من:</p>
<ul>
<li><strong>اسم النطاق والاستضافة</strong>: هل هما مشمولان، ولأي مدة؟ ومن يملكهما؟</li>
<li><strong>الصيانة</strong>: التحديثات، الأمان، النسخ الاحتياطية. الموقع غير المُتعهَّد يصبح بطيئاً وعرضة للاختراق.</li>
<li><strong>التعديلات</strong>: هل يمكنك تغيير سعر أو صورة بنفسك، أم يجب الدفع مقابل كل تدخل؟</li>
<li><strong>المحتوى</strong>: هل النصوص والصور مُقدَّمة، أم على عاتقك؟</li>
</ul>

<h2 id="nos-prix">أسعارنا في AMweb</h2>
<p>في AMweb نعرض أسعارنا بوضوح، مع <strong>تسهيلات في الأداء</strong> على جميع العروض:</p>
<div class="prose-prices">
  <a href="../offres.html#vitrine"><span>موقع تعريفي</span><strong>{{prix:vitrine}} MAD</strong><small>3 صفحات حسب الطلب، تحسين أساسي لمحركات البحث، استضافة سنة مشمولة</small></a>
  <a href="../offres.html#ecommerce"><span>متجر إلكتروني</span><strong>{{prix:ecommerce}} MAD</strong><small>متجر متكامل، أداء إلكتروني مدمج، لوحة تحكم</small></a>
  <a href="../offres.html#premium"><span>موقع بريميوم</span><strong>{{prix:premium}}+ MAD</strong><small>تطبيق، CRM، تحسين متقدم لمحركات البحث، يُحدَّد السعر في موعد</small></a>
</div>
<p>مترددون بين عرضين؟ <a href="../offres.html#finder">أداة الاختيار في أربعة أسئلة</a> تقترح عليكم العرض الأنسب، مع سعره ومدة إنجازه الحقيقية.</p>

<h2 id="bien-choisir">كيف تختار جيداً</h2>
<p>الميزانية المناسبة ليست الأقل، بل التي تجلب لك أكبر عدد من العملاء. انطلق من هدفك (أن يجدك الناس، أن تبيع، أن تؤتمت عملك)، واطلب عرض سعر مفصلاً، وقارن ما هو مشمول فعلاً. وإذا كان لديك موقع، فابدأ بـ<a href="../index.html#audit">التدقيق المجاني خلال 48 ساعة</a>: سيخبرك بما يستحق التحسين فعلاً.</p>$amw$, $amw$[["كم يكلف موقع تعريفي في المغرب؟", "في AMweb، يكلف موقع تعريفي من 3 صفحات حسب الطلب {{prix:vitrine}} درهم، مع تحسين أساسي لمحركات البحث واستضافة سنة مشمولة. وتختلف أسعار السوق كثيراً حسب عدد الصفحات والتصميم والخصائص."], ["هل يمكن أداء ثمن الموقع على دفعات؟", "نعم. تقدم AMweb تسهيلات في الأداء على جميع عروضها، بجدول دفعات نتفق عليه معاً قبل انطلاق المشروع."]]$amw$::jsonb, $amw$[{"url": "https://ar.wikipedia.org/wiki/%D9%85%D9%88%D9%82%D8%B9_%D9%88%D9%8A%D8%A8", "label": "موقع ويب (ويكيبيديا)"}, {"url": "https://ar.wikipedia.org/wiki/%D8%AA%D8%AD%D8%B3%D9%8A%D9%86_%D9%85%D8%AD%D8%B1%D9%83%D8%A7%D8%AA_%D8%A7%D9%84%D8%A8%D8%AD%D8%AB", "label": "تحسين محركات البحث (ويكيبيديا)"}]$amw$::jsonb, $amw$سعر موقع إلكتروني المغرب, كم يكلف موقع إلكتروني, ثمن إنشاء موقع, سعر موقع تعريفي, سعر متجر إلكتروني المغرب$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$site-vitrine-ou-e-commerce$amw$, $amw$ar$amw$, 2, $amw$موقع تعريفي أم متجر إلكتروني: أيهما تختار؟ | AMweb المغرب$amw$, $amw$موقع تعريفي أم متجر إلكتروني: أيهما يناسب نشاطك؟$amw$, $amw$موقع تعريفي أم متجر إلكتروني: الفروق، المزايا، أمثلة واقعية من المغرب، وطريقة بسيطة لاختيار العرض المناسب لنشاطك.$amw$, $amw$اختيار الموقع$amw$, $amw$web$amw$, $amw$غالباً ما يكون هذا أول قرار في أي مشروع ويب. لكن الجواب بسيط بمجرد طرح السؤال الصحيح: هل يجب أن يتمكن عملاؤك من الشراء مباشرة من موقعك؟$amw$, $amw$<h2 id="definitions">أداتان ومهمتان</h2>
<p><strong>الموقع التعريفي</strong> يقدّم ويطمئن. يعرض خدماتك وأعمالك ومواعيد عملك، ويدفع الزائر إلى الاتصال بك أو مراسلتك عبر واتساب أو زيارتك.</p>
<p><strong>المتجر الإلكتروني</strong> يبيع. يضيف كتالوجاً وسلة مشتريات ومرحلة أداء ولوحة تحكم لتسيير الطلبات. وهذا ما تسميه ويكيبيديا <a href="https://ar.wikipedia.org/wiki/%D8%AA%D8%AC%D8%A7%D8%B1%D8%A9_%D8%A5%D9%84%D9%83%D8%AA%D8%B1%D9%88%D9%86%D9%8A%D8%A9" target="_blank" rel="noopener">التجارة الإلكترونية</a>: تبادل السلع والخدمات عبر الإنترنت.</p>

<h2 id="quand-vitrine">متى تختار موقعاً تعريفياً</h2>
<ul>
<li>تبيع <strong>خدمة</strong> (عيادة، مكتب، وكالة، حرفي، مدرسة، مطعم).</li>
<li>تُختم مبيعاتك عبر الهاتف أو واتساب أو في المحل.</li>
<li>تريد أولاً <strong>الظهور على Google</strong> وكسب الثقة.</li>
</ul>
<p>في AMweb، يكلف <a href="../offres.html#vitrine">الموقع التعريفي</a> {{prix:vitrine}} درهم مقابل 3 صفحات حسب الطلب، يُسلَّم خلال أسبوع إلى أسبوعين.</p>

<h2 id="quand-ecommerce">متى تختار متجراً إلكترونياً</h2>
<ul>
<li>تبيع <strong>منتجات</strong> بأسعار ثابتة.</li>
<li>تتلقى أسئلة متكررة كثيرة («بكم هذا؟»، «هل ما زال المقاس M متوفراً؟»).</li>
<li>تريد البيع <strong>على مدار الساعة</strong>، حتى عندما يكون المحل مغلقاً.</li>
</ul>
<p>يكلف <a href="../offres.html#ecommerce">المتجر الإلكتروني</a> من AMweb {{prix:ecommerce}} درهم: صفحات غير محدودة، أداء إلكتروني مدمج، لوحة تحكم وتحسين متقدم لمحركات البحث.</p>

<h2 id="hybride">الحل الوسط، المنتشر كثيراً في المغرب</h2>
<p>تبدأ كثير من المحلات المغربية بكتالوج على الإنترنت والطلب عبر واتساب، ثم تنتقل إلى الأداء الإلكتروني عندما يرتفع حجم الطلبات. إنها استراتيجية جيدة: تختبر الطلب دون بناء كل شيء من اليوم الأول. وفي جميع الحالات، يجب أن يكون موقعك مقروءاً تماماً على الهاتف: هذا هو مبدأ <a href="https://ar.wikipedia.org/wiki/%D8%AA%D8%B5%D9%85%D9%8A%D9%85_%D9%85%D8%AA%D8%AC%D8%A7%D9%88%D8%A8" target="_blank" rel="noopener">التصميم المستجيب</a>.</p>

<h2 id="methode">الطريقة في ثلاثة أسئلة</h2>
<ol>
<li>هل يستطيع عملاؤك الشراء دون التحدث إليك؟ إذا كان الجواب نعم، ففكّر في المتجر الإلكتروني.</li>
<li>هل لديك أكثر من 3 صفحات من المحتوى لعرضها؟ إذا كان الجواب نعم، فقارن بين العرضين.</li>
<li>هل تحتاج أدوات خاصة (CRM، فضاء للعملاء، تطبيق)؟ إذن اطّلع على <a href="../offres.html#premium">موقع بريميوم</a>.</li>
</ol>
<p>لتقرر بسرعة، جرّب <a href="../offres.html#finder">أداة اختيار العرض</a>: أربعة أسئلة وتوصية واضحة.</p>$amw$, $amw$[["ما الفرق بين الموقع التعريفي والمتجر الإلكتروني؟", "الموقع التعريفي يقدّم نشاطك ويدفع الزائر إلى التواصل معك. أما المتجر الإلكتروني فيتيح الشراء مباشرة عبر الإنترنت بسلة مشتريات وأداء."], ["هل يمكن تحويل موقع تعريفي إلى متجر إلكتروني لاحقاً؟", "نعم. يمكن البدء بموقع تعريفي ثم الانتقال إلى المتجر الإلكتروني عندما تكون مستعداً للبيع عبر الإنترنت."]]$amw$::jsonb, $amw$[{"url": "https://ar.wikipedia.org/wiki/%D8%AA%D8%AC%D8%A7%D8%B1%D8%A9_%D8%A5%D9%84%D9%83%D8%AA%D8%B1%D9%88%D9%86%D9%8A%D8%A9", "label": "تجارة إلكترونية (ويكيبيديا)"}, {"url": "https://ar.wikipedia.org/wiki/%D8%AA%D8%B5%D9%85%D9%8A%D9%85_%D9%85%D8%AA%D8%AC%D8%A7%D9%88%D8%A8", "label": "التصميم المستجيب لمواقع الويب (ويكيبيديا)"}, {"url": "https://ar.wikipedia.org/wiki/%D9%85%D9%88%D9%82%D8%B9_%D9%88%D9%8A%D8%A8", "label": "موقع ويب (ويكيبيديا)"}]$amw$::jsonb, $amw$موقع تعريفي أم متجر إلكتروني, الفرق بين موقع تعريفي ومتجر إلكتروني, إنشاء متجر إلكتروني المغرب, موقع تعريفي المغرب$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$pourquoi-un-site-web-entreprise-kenitra$amw$, $amw$ar$amw$, 3, $amw$لماذا تحتاج شركتك في القنيطرة إلى موقع إلكتروني سنة 2026 | AMweb$amw$, $amw$لماذا تحتاج شركتك في القنيطرة إلى موقع إلكتروني سنة 2026$amw$, $amw$35.5 مليون مغربي يستخدمون الإنترنت. لماذا لم تعد صفحة فيسبوك كافية، وما الذي يغيّره موقع حقيقي لشركة في القنيطرة.$amw$, $amw$استراتيجية محلية$amw$, $amw$seo$amw$, $amw$عملاؤك المستقبليون يحملون هواتفهم بالفعل. السؤال الحقيقي لم يعد هل يبحثون عنك على الإنترنت، بل هل يجدونك، وماذا يرون عندما يصلون إليك.$amw$, $amw$<h2 id="chiffres">أرقام تغيّر كل شيء</h2>
<p>حسب <a href="https://datareportal.com/reports/digital-2026-morocco" target="_blank" rel="noopener">تقرير Digital 2026 الصادر عن DataReportal</a> المنشور في نهاية 2025:</p>
<ul>
<li><strong>35.5 مليون</strong> شخص يستخدمون الإنترنت في المغرب، أي <strong>92.2%</strong> من السكان؛</li>
<li><strong>22.8 مليون</strong> حساب نشط على شبكات التواصل الاجتماعي؛</li>
<li>يضم البلد <strong>57.1 مليون</strong> اشتراك في الهاتف المحمول، أكثر من عدد السكان.</li>
</ul>
<p>بعبارة أخرى، يمكن الوصول إلى جميع عملائك المحتملين تقريباً عبر الإنترنت، وأساساً عبر الهاتف.</p>

<h2 id="kenitra">القنيطرة، مدينة في تسارع</h2>
<p>تحتضن <a href="https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%82%D9%86%D9%8A%D8%B7%D8%B1%D8%A9_(%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8)" target="_blank" rel="noopener">القنيطرة</a> المنطقة الحرة الأطلسية، إحدى أكبر مناطق التصدير الحرة في القارة، ومصنعاً لتجميع السيارات تابعاً لمجموعة Stellantis. هذه الدينامية تجذب الشركات والمناولين والسكان الجدد. وبالنسبة لمحل أو عيادة أو مقاولة محلية، فهي فرصة، بشرط أن تكون ظاهراً حيث يبحث هؤلاء العملاء الجدد: على Google.</p>

<h2 id="reseaux">لماذا لا تكفي صفحة فيسبوك أو إنستغرام</h2>
<ul>
<li><strong>أنت لست في بيتك.</strong> الخوارزمية هي من يقرر من يرى منشوراتك، ويمكن أن يُحظر الحساب بين ليلة وضحاها.</li>
<li><strong>Google يعرض المواقع أولاً.</strong> عندما يكتب أحدهم «طبيب أسنان القنيطرة» أو «ممون حفلات القنيطرة»، فإنه يقارن بين المواقع وبطاقات Google، لا بين القصص.</li>
<li><strong>المصداقية.</strong> موقع احترافي يعرض أسعارك وأعمالك ومعلومات التواصل معك يطمئن أكثر من سلسلة منشورات.</li>
</ul>
<p>تبقى شبكات التواصل ضرورية لجذب الانتباه. أما الموقع فيحوّل هذا الانتباه إلى طلبات.</p>

<h2 id="benefices">ما الذي يغيّره موقع حقيقي فعلياً</h2>
<ol>
<li>يجدك الناس على Google، بمن فيهم عملاء لا يعرفونك بعد.</li>
<li>تجيب عن الأسئلة المتكررة (الأسعار، المواعيد، العنوان) قبل أن يتصل بك أحد.</li>
<li>تتلقى طلبات مؤهلة، مباشرة على واتساب.</li>
<li>تحتفظ بالتحكم في صورتك ومحتواك.</li>
<li>يمكنك البيع عبر الإنترنت عندما تكون مستعداً.</li>
</ol>

<h2 id="commencer">من أين تبدأ</h2>
<p>ابدأ ببساطة وبإتقان: <a href="../offres.html#vitrine">موقع تعريفي من 3 صفحات</a>، سريع وواضح ومُحسَّن لـ Google، يكفي لإحداث الفرق. وإذا أردت أن تعرف ما يتفوق فيه منافسوك عليك، فاطلب <a href="../index.html#audit">التدقيق المجاني</a>.</p>$amw$, $amw$[["كم عدد المغاربة الذين يستخدمون الإنترنت؟", "حسب DataReportal (تقرير Digital 2026)، يستخدم 35.5 مليون شخص الإنترنت في المغرب، أي 92.2% من السكان."], ["هل تكفي صفحة فيسبوك لشركة؟", "تساعد على جذب الانتباه، لكنها لا تعوّض الموقع: Google يُبرز المواقع وبطاقات المؤسسات، ولا تتحكم أنت في مدى وصول منشوراتك على شبكات التواصل."]]$amw$::jsonb, $amw$[{"url": "https://datareportal.com/reports/digital-2026-morocco", "label": "DataReportal، تقرير Digital 2026 عن المغرب"}, {"url": "https://ar.wikipedia.org/wiki/%D8%A7%D9%84%D9%82%D9%86%D9%8A%D8%B7%D8%B1%D8%A9_(%D8%A7%D9%84%D9%85%D8%BA%D8%B1%D8%A8)", "label": "القنيطرة (ويكيبيديا)"}, {"url": "https://ar.wikipedia.org/wiki/%D9%85%D9%88%D9%82%D8%B9_%D9%88%D9%8A%D8%A8", "label": "موقع ويب (ويكيبيديا)"}]$amw$::jsonb, $amw$موقع إلكتروني لشركة القنيطرة, لماذا موقع إلكتروني, تصميم مواقع القنيطرة, الظهور على الإنترنت المغرب$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$apparaitre-sur-google-maps-kenitra$amw$, $amw$ar$amw$, 4, $amw$كيف تظهر على خرائط Google وفي أعلى نتائج البحث في القنيطرة | AMweb$amw$, $amw$كيف تظهر على خرائط Google وفي أعلى نتائج البحث في القنيطرة$amw$, $amw$دليل عملي لتحسين الظهور المحلي: بطاقة Google Business Profile، آراء العملاء، توحيد معلومات التواصل، وموقع مُحسَّن ليجدك الناس في القنيطرة.$amw$, $amw$الظهور المحلي$amw$, $amw$listen$amw$, $amw$عندما يبحث أحدهم عن «مطعم القنيطرة» أو «سبّاك قريب مني»، يعرض Google أولاً خريطة بثلاث مؤسسات. أن تكون ضمن هذه الثلاث قد يملأ جدول مواعيدك. إليك كيف تضاعف حظوظك.$amw$, $amw$<h2 id="fiche">1. أنشئ بطاقة Google Business Profile وفعّلها</h2>
<p>بطاقة المؤسسة مجانية. تُنشأ عبر <a href="https://www.google.com/intl/ar/business/" target="_blank" rel="noopener">Google Business Profile</a>. وسيطلب منك Google التحقق من أنك صاحب النشاط قبل عرضها بالكامل.</p>
<ul>
<li>اختر <strong>الفئة الرئيسية</strong> الأدق الممكنة (مثلاً «مصمم مواقع ويب» بدلاً من «شركة»).</li>
<li>املأ <strong>العنوان والهاتف ومواعيد العمل والموقع الإلكتروني</strong>.</li>
<li>أضف <strong>صوراً حقيقية</strong>: الواجهة، الفريق، المنتجات، الأعمال المنجزة.</li>
</ul>

<h2 id="avis">2. اجمع آراء العملاء بانتظام</h2>
<p>للآراء وزن كبير في الترتيب المحلي وفي قرار العميل. اطلب رأياً من كل عميل راضٍ، مع رابط مباشر (إرساله عبر واتساب هو الأكثر فعالية). ورُدّ على جميع الآراء، الإيجابية والسلبية، بلباقة.</p>

<h2 id="coherence">3. وحّد معلومات التواصل في كل مكان</h2>
<p>يجب أن يُكتب الاسم والعنوان والهاتف بالطريقة نفسها تماماً في بطاقة Google وموقعك وشبكات التواصل والأدلة. هذا التوحيد يساعد Google على الوثوق بمعلوماتك.</p>

<h2 id="site">4. امتلك موقعاً مصمماً للظهور المحلي</h2>
<p>بطاقتك تحيل إلى موقعك: يجب أن يؤكد ما يراه Google. عملياً:</p>
<ul>
<li>اذكر مدينتك وحيّك في العناوين والنصوص، بشكل طبيعي؛</li>
<li>أنشئ صفحة لكل خدمة مهمة؛</li>
<li>اعتنِ بالسرعة على الهاتف (اختبرها عبر <a href="https://pagespeed.web.dev/" target="_blank" rel="noopener">PageSpeed Insights</a>)؛</li>
<li>أضف البيانات المنظمة من نوع «LocalBusiness» التي تصف نشاطك لـ Google.</li>
</ul>
<p>هذه الممارسات الجيدة جزء من <a href="https://ar.wikipedia.org/wiki/%D8%AA%D8%AD%D8%B3%D9%8A%D9%86_%D9%85%D8%AD%D8%B1%D9%83%D8%A7%D8%AA_%D8%A7%D9%84%D8%A8%D8%AD%D8%AB" target="_blank" rel="noopener">تحسين محركات البحث</a>، وهي مفصلة في <a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=ar" target="_blank" rel="noopener">الدليل الرسمي من Google</a>.</p>

<h2 id="contenu">5. انشر محتوى مفيداً</h2>
<p>الصفحات التي تجيب عن الأسئلة الحقيقية لعملائك (الأسعار، الآجال، النصائح) تجذب زواراً مؤهلين وتُظهر خبرتك. وهذا بالضبط ما تفعله هذه الصفحة.</p>

<h2 id="patience">كم من الوقت لرؤية النتائج؟</h2>
<p>تحسين الظهور عمل على المدى الطويل. يستغرق عادة من بضعة أسابيع إلى بضعة أشهر حسب المنافسة في قطاعك. لا أحد يستطيع ضمان المرتبة الأولى، لكن بطاقة مكتملة وآراء منتظمة وموقعاً متيناً تصنع فرقاً حقيقياً. تحتاج مساعدة؟ خدمة <a href="../index.html#services">تحسين محركات البحث</a> لدينا تتكفل بكل شيء، و<a href="../index.html#audit">التدقيق المجاني</a> يخبرك أين تقف.</p>$amw$, $amw$[["هل بطاقة Google Business Profile مجانية؟", "نعم، إنشاء بطاقة Google Business Profile وتسييرها مجانيان."], ["هل يمكن ضمان المرتبة الأولى على خرائط Google؟", "لا، لا أحد يستطيع ضمان ذلك. لكن بطاقة مكتملة ومُفعَّلة، وآراء منتظمة، ومعلومات تواصل موحدة، وموقعاً مُحسَّناً ترفع حظوظك بشكل كبير."]]$amw$::jsonb, $amw$[{"url": "https://www.google.com/intl/ar/business/", "label": "Google Business Profile"}, {"url": "https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=ar", "label": "Google Search Central، دليل تحسين محركات البحث للمبتدئين"}, {"url": "https://ar.wikipedia.org/wiki/%D8%AA%D8%AD%D8%B3%D9%8A%D9%86_%D9%85%D8%AD%D8%B1%D9%83%D8%A7%D8%AA_%D8%A7%D9%84%D8%A8%D8%AD%D8%AB", "label": "تحسين محركات البحث (ويكيبيديا)"}, {"url": "https://pagespeed.web.dev/", "label": "Google PageSpeed Insights"}]$amw$::jsonb, $amw$الظهور على خرائط Google, تحسين الظهور المحلي القنيطرة, بطاقة Google Business القنيطرة, تحسين محركات البحث المغرب$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$crm-pme-maroc$amw$, $amw$ar$amw$, 5, $amw$نظام CRM: ما فائدته لمقاولة مغربية صغيرة أو متوسطة؟ | AMweb$amw$, $amw$نظام CRM: ما فائدته لمقاولة مغربية صغيرة أو متوسطة؟$amw$, $amw$تعريف بسيط لنظام CRM، العلامات التي تدل على حاجة شركتك إليه، CRM جاهز أم حسب الطلب، وكيف تربطه بموقعك وبواتساب.$amw$, $amw$أدوات التسيير$amw$, $amw$apps$amw$, $amw$جهات اتصال في هاتف، عروض أسعار في Excel، متابعات منسية على واتساب: إذا كان هذا المشهد مألوفاً لديك، فقد يوفر لك نظام CRM الوقت ويكسبك عملاء.$amw$, $amw$<h2 id="definition">ما هو نظام CRM؟</h2>
<p>نظام CRM (Customer Relationship Management)، أي <a href="https://ar.wikipedia.org/wiki/%D8%A5%D8%AF%D8%A7%D8%B1%D8%A9_%D8%B9%D9%84%D8%A7%D9%82%D8%A7%D8%AA_%D8%A7%D9%84%D8%B9%D9%85%D9%84%D8%A7%D8%A1" target="_blank" rel="noopener">إدارة علاقات العملاء</a>، أداة تجمع في مكان واحد كل ما يتعلق بعملائك والمهتمين بخدماتك: معلومات التواصل، المحادثات، عروض الأسعار، الطلبات والمتابعات.</p>

<h2 id="signes">علامات تدل على أنك تحتاجه</h2>
<ul>
<li>تضيع منك طلبات لأنها تصل عبر قنوات كثيرة (الهاتف، واتساب، إنستغرام، الاستمارات).</li>
<li>لا تعرف عدد عروض الأسعار المعلقة، ولا أيها يحتاج إلى متابعة.</li>
<li>عدة أشخاص في الفريق يجيبون العملاء دون الاطلاع على السجل السابق.</li>
<li>تريد أرقاماً: من أين يأتي عملاؤك، وكم يدر عليك كل مصدر.</li>
</ul>

<h2 id="benefices">ما الذي يغيّره نظام CRM يومياً</h2>
<ol>
<li><strong>كل شيء في مكان واحد</strong>: لكل عميل بطاقة تضم سجله الكامل.</li>
<li><strong>لا متابعة منسية</strong>: تذكيرات تلقائية لعروض الأسعار والمواعيد.</li>
<li><strong>فريق منسجم</strong>: الجميع يرى مرحلة كل ملف.</li>
<li><strong>قرارات مبنية على الأرقام</strong>: لوحات قيادة بسيطة وواضحة.</li>
</ol>

<h2 id="marche-ou-mesure">CRM جاهز أم CRM حسب الطلب؟</h2>
<p>تناسب أنظمة CRM الجاهزة كثيراً من الشركات، لكنها تفرض منطقها الخاص، وغالباً باللغة الإنجليزية فقط، مع اشتراك عن كل مستخدم. أما نظام CRM <strong>حسب الطلب</strong> فيتكيّف مع مهنتك: مراحل البيع لديك، وثائقك، أدوار فريقك، بالفرنسية أو العربية. ويرتبط مباشرة بموقعك الإلكتروني (كل استمارة تنشئ بطاقة عميل) وبالأدوات التي تستعملها حالياً.</p>

<h2 id="connecter">اربطه بموقعك وبواتساب</h2>
<p>تظهر القوة الحقيقية عندما يرتبط نظام CRM بقنواتك: طلب على موقعك ينشئ بطاقة تلقائياً، وتُرسَل رسالة تأكيد، وتُبرمَج المتابعة. النتيجة: إدخال أقل للبيانات، وتجاوب أسرع.</p>

<h2 id="prix">كم يكلف؟</h2>
<p>في AMweb، تندرج أنظمة CRM والتطبيقات حسب الطلب ضمن <a href="../offres.html#premium">موقع بريميوم</a>، ابتداءً من {{prix:premium}} درهم. ويُحدَّد السعر النهائي معاً خلال موعد، حسب احتياجاتك، مع تسهيلات في الأداء. اكتشف أيضاً خبرتنا في <a href="../index.html#services">التطبيقات وأنظمة CRM</a>.</p>$amw$, $amw$[["ما هو نظام CRM؟", "نظام CRM (إدارة علاقات العملاء) أداة تجمع المعلومات المتعلقة بعملائك والمهتمين بخدماتك: معلومات التواصل، المحادثات، عروض الأسعار، الطلبات والمتابعات."], ["كم يكلف نظام CRM حسب الطلب في المغرب؟", "في AMweb، تندرج أنظمة CRM حسب الطلب ضمن موقع بريميوم، ابتداءً من {{prix:premium}} درهم. ويُحدَّد السعر النهائي خلال موعد حسب احتياجاتك."]]$amw$::jsonb, $amw$[{"url": "https://ar.wikipedia.org/wiki/%D8%A5%D8%AF%D8%A7%D8%B1%D8%A9_%D8%B9%D9%84%D8%A7%D9%82%D8%A7%D8%AA_%D8%A7%D9%84%D8%B9%D9%85%D9%84%D8%A7%D8%A1", "label": "إدارة علاقات العملاء (ويكيبيديا)"}]$amw$::jsonb, $amw$CRM المغرب, نظام CRM للمقاولات الصغيرة, برنامج تسيير العملاء المغرب, CRM حسب الطلب, تطبيق تسيير المقاولة$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
insert into public.articles (slug, lang, ordre, titre_seo, h1, description, categorie, image, chapo, corps, faq, sources, mots_cles, publie, date_pub) values ($amw$vendre-en-ligne-au-maroc$amw$, $amw$ar$amw$, 6, $amw$البيع عبر الإنترنت في المغرب: الأداء، التوصيل والقواعد الواجب معرفتها | AMweb$amw$, $amw$البيع عبر الإنترنت في المغرب: الأداء، التوصيل والقواعد الواجب معرفتها$amw$, $amw$إطلاق متجر إلكتروني في المغرب: وسائل الأداء، الدفع عند الاستلام، التوصيل، الالتزامات القانونية (القانون 31.08 والقانون 09.08) والصفحات الضرورية.$amw$, $amw$التجارة الإلكترونية$amw$, $amw$marketing$amw$, $amw$لم يكن فتح متجر إلكتروني في المغرب أسهل مما هو عليه اليوم. لكن المتجر الذي يبيع فعلاً يقوم على بعض الاختيارات الأساسية: كيف يؤدي عملاؤك، وكيف تصلهم طلباتهم، وما الذي يطمئنهم قبل الشراء.$amw$, $amw$<h2 id="produits">ابدأ بمنتجاتك</h2>
<p>أفضل المتاجر تبدأ بعرض واضح: بضعة منتجات رئيسية معروضة بعناية أفضل من كتالوج ضخم بأوصاف رديئة. يجب أن تتضمن كل صفحة منتج صوراً حقيقية وسعراً ووصفاً دقيقاً وآجال التوصيل.</p>

<h2 id="paiement">وسائل الأداء</h2>
<ul>
<li><strong>الأداء بالبطاقة البنكية</strong>: في المغرب، يمر عبر حل أداء مرتبط بـ <a href="https://www.cmi.co.ma/" target="_blank" rel="noopener">مركز CMI</a> أو عبر مزود معتمد، من خلال بنكك.</li>
<li><strong>الدفع عند الاستلام</strong>: منتشر جداً في المغرب، ويطمئن العملاء الذين يطلبون لأول مرة.</li>
<li><strong>التحويل البنكي</strong>: مفيد للطلبات الكبيرة أو للعملاء المهنيين.</li>
</ul>
<p>اقتراح عدة خيارات يقلل من التخلي عن سلة المشتريات. <a href="../offres.html#ecommerce">المتجر الإلكتروني من AMweb</a> يدمج الأداء الإلكتروني ويتكيّف مع هذه الوسائل.</p>

<h2 id="livraison">التوصيل</h2>
<p>اختر شريك توصيل موثوقاً يغطي مدن عملائك، واعرض المصاريف والآجال بوضوح، وأرسل رسالة تتبع. التوصيل الجيد يحوّل الشراء الأول إلى عميل وفيّ.</p>

<h2 id="regles">القواعد الواجب معرفتها</h2>
<ul>
<li><strong>حماية المستهلك</strong>: يؤطر القانون 31.08 البيع عن بعد، خاصة إعلام العميل وحق التراجع.</li>
<li><strong>المعطيات الشخصية</strong>: يفرض القانون 09.08 حماية معطيات عملائك وإخبارهم بكيفية استعمالها. و<a href="https://www.cndp.ma/" target="_blank" rel="noopener">اللجنة الوطنية لمراقبة حماية المعطيات ذات الطابع الشخصي (CNDP)</a> هي السلطة المختصة.</li>
<li><strong>الصفحات الإلزامية</strong>: الإشعارات القانونية، الشروط العامة للبيع، سياسة الخصوصية.</li>
</ul>
<p>اعرض شروطك العامة على مهني في القانون لمراجعتها: هذا الدليل لا يعوّض استشارة قانونية.</p>

<h2 id="confiance">ما الذي يطمئن قبل الشراء</h2>
<ol>
<li>موقع سريع ومثالي على الهاتف؛</li>
<li>آراء عملاء ظاهرة؛</li>
<li>رقم واتساب لطرح الأسئلة؛</li>
<li>شروط إرجاع واضحة؛</li>
<li>موقع مؤمَّن بـ HTTPS.</li>
</ol>

<h2 id="lancer">مستعد للانطلاق؟</h2>
<p><a href="https://ar.wikipedia.org/wiki/%D8%AA%D8%AC%D8%A7%D8%B1%D8%A9_%D8%A5%D9%84%D9%83%D8%AA%D8%B1%D9%88%D9%86%D9%8A%D8%A9" target="_blank" rel="noopener">التجارة الإلكترونية</a> تكافئ من يبدأ بشكل جيد. <a href="../offres.html#ecommerce">متجرنا الإلكتروني بـ {{prix:ecommerce}} درهم</a> يشمل متجراً متكاملاً، أداءً إلكترونياً مدمجاً، لوحة تحكم، تحسيناً متقدماً لمحركات البحث ودعماً ذا أولوية، مع تسهيلات في الأداء. اقرأ أيضاً مقارنتنا <a href="site-vitrine-ou-e-commerce.html">موقع تعريفي أم متجر إلكتروني</a>.</p>$amw$, $amw$[["هل يمكن اعتماد الدفع عند الاستلام في متجر إلكتروني؟", "نعم، وهو منتشر جداً في المغرب. ويمكن اقتراحه إلى جانب الأداء بالبطاقة لطمأنة العملاء الجدد."], ["ما الصفحات القانونية التي يحتاجها متجر إلكتروني في المغرب؟", "على الأقل الإشعارات القانونية، والشروط العامة للبيع، وسياسة خصوصية مطابقة للقانون 09.08. اعرضها على مهني في القانون لمراجعتها."]]$amw$::jsonb, $amw$[{"url": "https://ar.wikipedia.org/wiki/%D8%AA%D8%AC%D8%A7%D8%B1%D8%A9_%D8%A5%D9%84%D9%83%D8%AA%D8%B1%D9%88%D9%86%D9%8A%D8%A9", "label": "تجارة إلكترونية (ويكيبيديا)"}, {"url": "https://www.cmi.co.ma/", "label": "CMI (Centre Monétique Interbancaire)"}, {"url": "https://www.cndp.ma/", "label": "اللجنة الوطنية لمراقبة حماية المعطيات ذات الطابع الشخصي (CNDP)"}]$amw$::jsonb, $amw$البيع عبر الإنترنت المغرب, إنشاء متجر إلكتروني المغرب, الأداء الإلكتروني المغرب, التجارة الإلكترونية المغرب, الدفع عند الاستلام$amw$, true, $amw$2026-10-11$amw$) on conflict (slug, lang) do nothing;
